CREATE TABLE "organizations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "organizations_name_key" ON "organizations" ("name");
CREATE TABLE "devices" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "device_id" character varying NOT NULL, "name" character varying NOT NULL, "type" character varying NOT NULL, "properties" jsonb NULL, "version" bigint NOT NULL DEFAULT 0, "state" character varying NOT NULL DEFAULT 'active', "source" character varying NULL, "source_synced_at" timestamptz NULL, "tags" jsonb NULL, "device_children" bigint NULL, "organization_devices" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "devices_devices_children" FOREIGN KEY ("device_children") REFERENCES "devices" ("id") ON DELETE SET NULL, CONSTRAINT "devices_organizations_devices" FOREIGN KEY ("organization_devices") REFERENCES "organizations" ("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "devices_device_id_key" ON "devices" ("device_id");
CREATE UNIQUE INDEX "devices_name_key" ON "devices" ("name");
CREATE INDEX "device_device_id" ON "devices" ("device_id");
CREATE TABLE "facts" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "payload" jsonb NOT NULL, "hash" character varying NOT NULL, "device_facts" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "facts_devices_facts" FOREIGN KEY ("device_facts") REFERENCES "devices" ("id") ON DELETE NO ACTION);
CREATE TABLE "groups" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "groups_name_key" ON "groups" ("name");
CREATE TABLE "group_children" ("group_id" bigint NOT NULL, "parent_id" bigint NOT NULL, PRIMARY KEY ("group_id", "parent_id"), CONSTRAINT "group_children_group_id" FOREIGN KEY ("group_id") REFERENCES "groups" ("id") ON DELETE CASCADE, CONSTRAINT "group_children_parent_id" FOREIGN KEY ("parent_id") REFERENCES "groups" ("id") ON DELETE CASCADE);
CREATE TABLE "group_devices" ("group_id" bigint NOT NULL, "device_id" bigint NOT NULL, PRIMARY KEY ("group_id", "device_id"), CONSTRAINT "group_devices_group_id" FOREIGN KEY ("group_id") REFERENCES "groups" ("id") ON DELETE CASCADE, CONSTRAINT "group_devices_device_id" FOREIGN KEY ("device_id") REFERENCES "devices" ("id") ON DELETE CASCADE);
CREATE TABLE "jobs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "job_id" character varying NOT NULL, "runbook_id" character varying NOT NULL, "group_name" character varying NOT NULL, "actor" character varying NOT NULL, "state" character varying NOT NULL DEFAULT 'pending', "dispatched_count" bigint NOT NULL DEFAULT 0, "skipped_count" bigint NOT NULL DEFAULT 0, "failed_count" bigint NOT NULL DEFAULT 0, "failure_reason" character varying NULL, "fence" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "jobs_job_id_key" ON "jobs" ("job_id");
CREATE TABLE "job_tasks" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "device_id" character varying NOT NULL, "device_name" character varying NOT NULL, "outcome" character varying NOT NULL, "reason" character varying NULL, "job_tasks" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "job_tasks_jobs_tasks" FOREIGN KEY ("job_tasks") REFERENCES "jobs" ("id") ON DELETE NO ACTION);
CREATE INDEX "jobtask_outcome_job_tasks" ON "job_tasks" ("outcome", "job_tasks");
CREATE TABLE "revisions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "version" bigint NOT NULL, "changed_at" timestamptz NOT NULL, "field_name" character varying NOT NULL, "old_value" jsonb NULL, "new_value" jsonb NULL, "device_revisions" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "revisions_devices_revisions" FOREIGN KEY ("device_revisions") REFERENCES "devices" ("id") ON DELETE NO ACTION);
CREATE INDEX "revision_version_device_revisions" ON "revisions" ("version", "device_revisions");
CREATE INDEX "revision_field_name" ON "revisions" ("field_name");
CREATE TABLE "teams" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "organization_teams" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "teams_organizations_teams" FOREIGN KEY ("organization_teams") REFERENCES "organizations" ("id") ON DELETE NO ACTION);
CREATE TABLE "role_bindings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "role" character varying NOT NULL, "scope_type" character varying NOT NULL, "scope_id" bigint NULL, "effect" character varying NOT NULL DEFAULT 'allow', "team_role_bindings" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "role_bindings_teams_role_bindings" FOREIGN KEY ("team_role_bindings") REFERENCES "teams" ("id") ON DELETE NO ACTION);
CREATE INDEX "rolebinding_scope_type_scope_id" ON "role_bindings" ("scope_type", "scope_id");
CREATE TABLE "users" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "email" character varying NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
CREATE TABLE "team_users" ("team_id" bigint NOT NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("team_id", "user_id"), CONSTRAINT "team_users_team_id" FOREIGN KEY ("team_id") REFERENCES "teams" ("id") ON DELETE CASCADE, CONSTRAINT "team_users_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE);
